"""Actual native two-action TV and Home screen presentation/input."""
from pathlib import Path
import runpy,tempfile,subprocess,re
stubs=dict(runpy.run_path('tests/test_setup_language.py')['stubs'])
stubs.pop('io/tvos/LanguageTest.java')
src=Path('app/src/io/tvos/SetupFinishView.java').read_text();ids=sorted(set(re.findall(r'R.string.(settings_\w+)',src)))
stubs['io/tvos/R.java']='package io.tvos;class R {static class string {'+''.join('static final int '+k+'='+str(i+1)+';' for i,k in enumerate(ids))+'}}'
stubs['io/tvos/AppStrings.java']='package io.tvos;class AppStrings {static String get(int id){return "text "+id;}}'
stubs['io/tvos/FinishTest.java']='''package io.tvos;import android.content.Context;import android.graphics.Canvas;import android.view.KeyEvent;class FinishTest {static void check(boolean b,String s){if(!b)throw new AssertionError(s);}static void ok(SetupFinishView v){v.onKeyDown(23,new KeyEvent(0,false));v.onKeyUp(23,new KeyEvent(0,false));}public static void main(String[] args){Context.reduced=true;int[] edit={0},next={0};SetupFinishView tv=new SetupFinishView(new Context(),true,"System TV",()->edit[0]++,()->next[0]++);Canvas c=new Canvas();tv.onDraw(c);check(c.texts.contains("System TV")&&c.paths==1,"detected app and native TV artwork");tv.application("Chosen TV");c=new Canvas();tv.onDraw(c);check(c.texts.contains("Chosen TV"),"choice label updates without navigation");check(c.active.equals(AppStrings.get(R.string.settings_setup_continue)),"Continue focused initially on TV screen");tv.onKeyDown(19,new KeyEvent(0,false));tv.onKeyUp(23,new KeyEvent(0,false));check(edit[0]==0,"orphan release ignored");tv.onKeyDown(23,new KeyEvent(0,false));tv.onWindowFocusChanged(false);check(c.active.equals(AppStrings.get(R.string.settings_setup_continue)),"Continue focused initially on TV screen");tv.onKeyDown(19,new KeyEvent(0,false));tv.onKeyUp(23,new KeyEvent(0,false));check(edit[0]==0,"focus loss cancels");ok(tv);check(edit[0]==1&&next[0]==0,"first button edits only");tv.onKeyDown(20,new KeyEvent(0,false));ok(tv);ok(tv);check(next[0]==1,"continue once");int[] home={0},later={0};SetupFinishView h=new SetupFinishView(new Context(),false,"",()->home[0]++,()->later[0]++);ok(h);ok(h);check(home[0]==1&&later[0]==0,"Home action once");h.onWindowFocusChanged(true);h.onKeyDown(20,new KeyEvent(0,false));ok(h);check(later[0]==1,"not now remains optional");h.onDetachedFromWindow();int[] automatic={0},manual={0};SetupFinishView weather=new SetupFinishView(new Context(),SetupFinishView.Kind.WEATHER,"Chisinau",()->automatic[0]++,()->manual[0]++);Canvas wc=new Canvas();weather.onDraw(wc);check(wc.paths==1&&wc.texts.contains("Chisinau"),"weather city and cached native icon");weather.status("No results");Canvas status=new Canvas();weather.onDraw(status);check(status.texts.contains("No results")&&status.texts.contains("Chisinau"),"search status is separate from city choice");ok(weather);weather.onKeyDown(20,new KeyEvent(0,false));ok(weather);check(automatic[0]==1&&manual[0]==1,"weather actions remain independent");Context.reduced=false;android.os.SystemClock.now=1000;SetupFinishView animated=new SetupFinishView(new Context(),true,"TV",()->{},()->{});Canvas entry=new Canvas();animated.onDraw(entry);check(entry.layerAlpha==0,"TV/Home/Weather surface starts on background");android.os.SystemClock.now+=130;Canvas half=new Canvas();animated.onDraw(half);check(half.layerAlpha>0&&half.layerAlpha<255,"final screens fade in");int[] exits={0};animated.leave(()->exits[0]++);android.os.SystemClock.now+=220;Canvas blank=new Canvas();animated.onDraw(blank);check(blank.layerAlpha==0&&exits[0]==0,"final screens fade to common background");android.os.SystemClock.now+=60;animated.onDraw(new Canvas());check(exits[0]==1,"final screens advance after background pause");System.out.println("PASS: actual TV/Home layout, live app label, edit/continue distinction, optional Home and focus/release guards");}}'''
with tempfile.TemporaryDirectory() as tmp:
 root=Path(tmp)
 for name,code in stubs.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(code)
 for name in ['SetupFinishView.java','setup/SetupArtwork.java','Spring.java']:
  p=root/'io/tvos'/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text((Path('app/src/io/tvos')/name).read_text())
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all,-options','-Werror','-d',tmp,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.FinishTest'],check=True,timeout=15)
